# @title 2. Bundle ATLAS LM (sem GitHub)
import base64, gzip, sys, importlib
from pathlib import Path

ATLAS_SOURCES = {
    "atlas/__init__.py": "\"\"\"ATLAS char-level language modeling experiments.\"\"\"\n",
    "atlas/models.py": "\"\"\"Minimal char-level transformer with global attention or causal long-conv FFT mixing.\"\"\"\n\nfrom __future__ import annotations\n\nimport math\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\n\nclass CausalSelfAttention(nn.Module):\n    def __init__(self, n_embd: int, n_head: int, dropout: float, block_size: int) -> None:\n        super().__init__()\n        assert n_embd % n_head == 0\n        self.n_head = n_head\n        self.head_dim = n_embd // n_head\n        self.qkv = nn.Linear(n_embd, 3 * n_embd)\n        self.proj = nn.Linear(n_embd, n_embd)\n        self.dropout = nn.Dropout(dropout)\n        self.register_buffer(\n            \"mask\",\n            torch.tril(torch.ones(block_size, block_size)).view(1, 1, block_size, block_size),\n        )\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        b, t, c = x.shape\n        qkv = self.qkv(x).reshape(b, t, 3, self.n_head, self.head_dim).permute(2, 0, 3, 1, 4)\n        q, k, v = qkv[0], qkv[1], qkv[2]\n        att = (q @ k.transpose(-2, -1)) / math.sqrt(self.head_dim)\n        att = att.masked_fill(self.mask[:, :, :t, :t] == 0, float(\"-inf\"))\n        att = F.softmax(att, dim=-1)\n        att = self.dropout(att)\n        y = (att @ v).transpose(1, 2).contiguous().view(b, t, c)\n        return self.dropout(self.proj(y))\n\n\nclass CausalTokenBlend(nn.Module):\n    \"\"\"NOVEL: mixing O(T) causal \u2014 depthwise conv1d + gate (sem QKV).\"\"\"\n\n    def __init__(self, n_embd: int, kernel: int = 3, dropout: float = 0.0) -> None:\n        super().__init__()\n        self.kernel = kernel\n        self.dw = nn.Conv1d(n_embd, n_embd, kernel, padding=0, groups=n_embd, bias=False)\n        nn.init.dirac_(self.dw.weight)\n        self.dropout = nn.Dropout(dropout)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        h = F.pad(x.transpose(1, 2), (self.kernel - 1, 0))\n        local = self.dw(h).transpose(1, 2)\n        gate = torch.sigmoid(x.mean(dim=1, keepdim=True))\n        return self.dropout(gate * local + (1.0 - gate) * x)\n\n\nclass CausalTokenBlendMS(nn.Module):\n    \"\"\"NOVEL: multi-scale causal token blend (kernels 3 + 5).\"\"\"\n\n    def __init__(self, n_embd: int, dropout: float = 0.0) -> None:\n        super().__init__()\n        self.dw3 = nn.Conv1d(n_embd, n_embd, 3, padding=0, groups=n_embd, bias=False)\n        self.dw5 = nn.Conv1d(n_embd, n_embd, 5, padding=0, groups=n_embd, bias=False)\n        nn.init.dirac_(self.dw3.weight)\n        nn.init.dirac_(self.dw5.weight)\n        self.dropout = nn.Dropout(dropout)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        h = x.transpose(1, 2)\n        h3 = self.dw3(F.pad(h, (2, 0)))\n        h5 = self.dw5(F.pad(h, (4, 0)))\n        local = (0.5 * h3 + 0.5 * h5).transpose(1, 2)\n        gate = torch.sigmoid(x.mean(dim=1, keepdim=True))\n        return self.dropout(gate * local + (1.0 - gate) * x)\n\n\nclass LongConvFFT(nn.Module):\n    \"\"\"Causal depthwise long convolution via FFT (pad to 2T-1, truncate to T).\"\"\"\n\n    def __init__(self, n_embd: int, kernel_size: int, dropout: float) -> None:\n        super().__init__()\n        self.kernel_size = kernel_size\n        self.filters = nn.Parameter(torch.randn(n_embd, kernel_size) * 0.02)\n        self.proj = nn.Linear(n_embd, n_embd)\n        self.dropout = nn.Dropout(dropout)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        b, t, c = x.shape\n        x_ch = x.transpose(1, 2)\n        n = 2 * t - 1\n        x_pad = F.pad(x_ch, (0, t - 1))\n        k = self.filters[:, : min(self.kernel_size, t)]\n        k_pad = F.pad(k, (0, n - k.shape[-1]))\n        x_f = torch.fft.rfft(x_pad, n=n)\n        k_f = torch.fft.rfft(k_pad, n=n).unsqueeze(0)\n        y_f = x_f * k_f\n        y = torch.fft.irfft(y_f, n=n)[..., :t]\n        y = y.transpose(1, 2)\n        return self.dropout(self.proj(y))\n\n\ndef build_norm(name: str, n_embd: int) -> nn.Module | None:\n    if name == \"none\":\n        return None\n    if name == \"layernorm\":\n        return nn.LayerNorm(n_embd)\n    raise ValueError(f\"Unknown norm: {name}\")\n\n\ndef build_activation(name: str) -> nn.Module:\n    if name == \"gelu\":\n        return nn.GELU()\n    if name == \"relu\":\n        return nn.ReLU()\n    raise ValueError(f\"Unknown activation: {name}\")\n\n\nclass Block(nn.Module):\n    def __init__(\n        self,\n        *,\n        n_embd: int,\n        n_head: int,\n        block_size: int,\n        dropout: float,\n        mixing: str,\n        norm: str,\n        activation: str,\n    ) -> None:\n        super().__init__()\n        self.ln1 = build_norm(norm, n_embd)\n        self.ln2 = build_norm(norm, n_embd)\n        if mixing == \"global-attn\":\n            self.mixer = CausalSelfAttention(n_embd, n_head, dropout, block_size)\n        elif mixing == \"long-conv-fft\":\n            self.mixer = LongConvFFT(n_embd, kernel_size=block_size, dropout=dropout)\n        elif mixing == \"token_blend\":\n            self.mixer = CausalTokenBlend(n_embd, kernel=3, dropout=dropout)\n        elif mixing == \"token_blend_ms\":\n            self.mixer = CausalTokenBlendMS(n_embd, dropout=dropout)\n        else:\n            raise ValueError(f\"Unknown mixing: {mixing}\")\n        self.ff = nn.Sequential(\n            nn.Linear(n_embd, 4 * n_embd),\n            build_activation(activation),\n            nn.Linear(4 * n_embd, n_embd),\n            nn.Dropout(dropout),\n        )\n\n    def _norm(self, ln: nn.Module | None, x: torch.Tensor) -> torch.Tensor:\n        return ln(x) if ln is not None else x\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        x = x + self.mixer(self._norm(self.ln1, x))\n        x = x + self.ff(self._norm(self.ln2, x))\n        return x\n\n\nclass CharLM(nn.Module):\n    def __init__(\n        self,\n        *,\n        vocab_size: int,\n        n_layer: int,\n        n_head: int,\n        n_embd: int,\n        block_size: int,\n        dropout: float,\n        mixing: str = \"global-attn\",\n        norm: str = \"layernorm\",\n        activation: str = \"gelu\",\n    ) -> None:\n        super().__init__()\n        self.block_size = block_size\n        self.token_emb = nn.Embedding(vocab_size, n_embd)\n        self.pos_emb = nn.Embedding(block_size, n_embd)\n        self.drop = nn.Dropout(dropout)\n        self.blocks = nn.ModuleList(\n            [\n                Block(\n                    n_embd=n_embd,\n                    n_head=n_head,\n                    block_size=block_size,\n                    dropout=dropout,\n                    mixing=mixing,\n                    norm=norm,\n                    activation=activation,\n                )\n                for _ in range(n_layer)\n            ]\n        )\n        self.ln_f = build_norm(norm, n_embd)\n        self.head = nn.Linear(n_embd, vocab_size, bias=False)\n\n    def forward(self, idx: torch.Tensor, targets: torch.Tensor | None = None):\n        b, t = idx.shape\n        pos = torch.arange(t, device=idx.device)\n        x = self.drop(self.token_emb(idx) + self.pos_emb(pos))\n        for block in self.blocks:\n            x = block(x)\n        if self.ln_f is not None:\n            x = self.ln_f(x)\n        logits = self.head(x)\n        loss = None\n        if targets is not None:\n            loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.view(-1))\n        return logits, loss\n",
    "atlas/datasets.py": "\"\"\"Char-level datasets for tinyshakespeare LM experiments.\"\"\"\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport torch\n\n\ndef build_vocab(text: str) -> tuple[dict[str, int], dict[int, str]]:\n    chars = sorted(set(text))\n    stoi = {ch: i for i, ch in enumerate(chars)}\n    itos = {i: ch for ch, i in stoi.items()}\n    return stoi, itos\n\n\nclass CharDataset:\n    \"\"\"Character dataset with optional shared vocabulary.\"\"\"\n\n    def __init__(\n        self,\n        text: str,\n        *,\n        stoi: dict[str, int] | None = None,\n        itos: dict[int, str] | None = None,\n    ) -> None:\n        if stoi is None:\n            stoi, itos = build_vocab(text)\n        self.stoi = stoi\n        self.itos = itos\n        self.vocab_size = len(stoi)\n        self.data = torch.tensor([stoi[c] for c in text], dtype=torch.long)\n\n    @classmethod\n    def from_file(\n        cls,\n        path: Path | str,\n        *,\n        stoi: dict[str, int],\n        itos: dict[int, str],\n    ) -> CharDataset:\n        text = Path(path).read_text(encoding=\"utf-8\")\n        return cls(text, stoi=stoi, itos=itos)\n\n\ndef load_train_val(\n    data_path: Path | str,\n    train_frac: float = 0.9,\n) -> tuple[CharDataset, CharDataset]:\n    \"\"\"Load train/val splits with vocabulary built from the full corpus.\"\"\"\n    text = Path(data_path).read_text(encoding=\"utf-8\")\n    split = int(train_frac * len(text))\n    stoi, itos = build_vocab(text)\n    train_ds = CharDataset(text[:split], stoi=stoi, itos=itos)\n    val_ds = CharDataset(text[split:], stoi=stoi, itos=itos)\n    assert train_ds.stoi == val_ds.stoi\n    assert train_ds.vocab_size == val_ds.vocab_size\n    return train_ds, val_ds\n\n\ndef random_batch(\n    data: torch.Tensor,\n    block_size: int,\n    batch_size: int,\n) -> tuple[torch.Tensor, torch.Tensor]:\n    \"\"\"Sample random contiguous chunks (high token diversity).\"\"\"\n    max_start = len(data) - block_size - 1\n    ix = torch.randint(max_start, (batch_size,))\n    x = torch.stack([data[i : i + block_size] for i in ix])\n    y = torch.stack([data[i + 1 : i + block_size + 1] for i in ix])\n    return x, y\n\n\ndef consecutive_batch(\n    data: torch.Tensor,\n    block_size: int,\n    batch_size: int,\n    start: int,\n) -> tuple[torch.Tensor, torch.Tensor]:\n    \"\"\"Buggy consecutive batches (for regression tests only).\"\"\"\n    x = torch.stack([data[start + i : start + i + block_size] for i in range(batch_size)])\n    y = torch.stack([data[start + i + 1 : start + i + block_size + 1] for i in range(batch_size)])\n    return x, y\n",
    "atlas/trainer.py": "\"\"\"Shared training loop for ATLAS char-level LM.\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport math\nimport random\nimport time\nfrom dataclasses import asdict, dataclass, field\nfrom pathlib import Path\nfrom typing import Any\n\nimport torch\n\nfrom atlas.datasets import load_train_val, random_batch\nfrom atlas.models import CharLM\nfrom atlas.optimizers import build_optimizer\n\n\n@dataclass\nclass LMTrainConfig:\n    tag: str = \"run\"\n    seed: int = 42\n    total_steps: int = 8000\n    eval_every: int = 1000\n    n_layer: int = 3\n    n_head: int = 4\n    n_embd: int = 64\n    block_size: int = 64\n    batch: int = 16\n    dropout: float = 0.1\n    lr: float = 1e-3\n    weight_decay: float = 0.01\n    mixing: str = \"global-attn\"\n    norm: str = \"layernorm\"\n    activation: str = \"gelu\"\n    optimizer: str = \"adamw\"\n    schedule: str = \"cosine\"\n    data_path: str = \"atlas/data/tinyshakespeare.txt\"\n    log_every: int = 200\n    grad_clip: float = 1.0\n    warmup_steps: int = 200\n    device: str = \"auto\"\n    amp: bool = False\n    label_smoothing: float = 0.0\n\n\n@dataclass\nclass LMTrainResult:\n    tag: str\n    seed: int\n    total_steps: int\n    wall_time_s: float\n    steps_per_sec: float\n    final_train_loss: float\n    final_val_loss: float\n    best_val_loss: float\n    val_losses: list[float] = field(default_factory=list)\n    config: dict[str, Any] = field(default_factory=dict)\n\n\ndef set_seed(seed: int) -> None:\n    random.seed(seed)\n    torch.manual_seed(seed)\n\n\ndef resolve_device(name: str) -> torch.device:\n    if name == \"auto\":\n        return torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n    return torch.device(name)\n\n\ndef lr_at_step(cfg: LMTrainConfig, step: int) -> float:\n    if cfg.schedule == \"none\":\n        return cfg.lr\n    if cfg.schedule == \"cosine\":\n        progress = step / max(cfg.total_steps, 1)\n        return cfg.lr * 0.5 * (1.0 + math.cos(math.pi * progress))\n    if cfg.schedule == \"cosine-warmup\":\n        if step < cfg.warmup_steps:\n            return cfg.lr * step / max(cfg.warmup_steps, 1)\n        progress = (step - cfg.warmup_steps) / max(cfg.total_steps - cfg.warmup_steps, 1)\n        return cfg.lr * 0.5 * (1.0 + math.cos(math.pi * progress))\n    raise ValueError(f\"Unknown schedule: {cfg.schedule}\")\n\n\n@torch.no_grad()\ndef evaluate(\n    model: CharLM, data: torch.Tensor, block_size: int, batch: int, device: torch.device\n) -> float:\n    model.eval()\n    losses = []\n    n_eval = min(20, max(1, (len(data) - block_size - 1) // batch))\n    for start in range(0, n_eval * batch, batch):\n        idx = torch.arange(start, start + batch)\n        x = torch.stack([data[i : i + block_size] for i in idx]).to(device)\n        y = torch.stack([data[i + 1 : i + block_size + 1] for i in idx]).to(device)\n        _, loss = model(x, y)\n        losses.append(loss.item())\n    return float(sum(losses) / len(losses))\n\n\ndef train_lm(cfg: LMTrainConfig) -> LMTrainResult:\n    set_seed(cfg.seed)\n    device = resolve_device(cfg.device)\n    use_amp = cfg.amp and device.type == \"cuda\"\n    if device.type == \"cpu\":\n        torch.set_num_threads(2)\n    if device.type == \"cuda\":\n        torch.backends.cuda.matmul.allow_tf32 = True\n    t0 = time.time()\n\n    train_ds, val_ds = load_train_val(cfg.data_path)\n    assert train_ds.stoi == val_ds.stoi\n    assert train_ds.vocab_size == val_ds.vocab_size\n\n    model = CharLM(\n        vocab_size=train_ds.vocab_size,\n        n_layer=cfg.n_layer,\n        n_head=cfg.n_head,\n        n_embd=cfg.n_embd,\n        block_size=cfg.block_size,\n        dropout=cfg.dropout,\n        mixing=cfg.mixing,\n        norm=cfg.norm,\n        activation=cfg.activation,\n    ).to(device)\n    opt = build_optimizer(cfg.optimizer, model.parameters(), cfg.lr, cfg.weight_decay)\n\n    val_losses: list[float] = []\n    best_val = float(\"inf\")\n    train_loss = 0.0\n\n    for step in range(1, cfg.total_steps + 1):\n        model.train()\n        lr = lr_at_step(cfg, step)\n        for pg in opt.param_groups:\n            pg[\"lr\"] = lr\n\n        x, y = random_batch(train_ds.data, cfg.block_size, cfg.batch)\n        x, y = x.to(device), y.to(device)\n        opt.zero_grad(set_to_none=True)\n        with torch.autocast(device_type=\"cuda\", dtype=torch.bfloat16, enabled=use_amp):\n            _, loss = model(x, y)\n        loss.backward()\n        if cfg.grad_clip > 0:\n            torch.nn.utils.clip_grad_norm_(model.parameters(), cfg.grad_clip)\n        opt.step()\n        train_loss = loss.item()\n\n        if step % cfg.eval_every == 0 or step == cfg.total_steps:\n            vloss = evaluate(model, val_ds.data, cfg.block_size, cfg.batch, device)\n            val_losses.append(vloss)\n            best_val = min(best_val, vloss)\n\n    wall = time.time() - t0\n    final_val = evaluate(model, val_ds.data, cfg.block_size, cfg.batch, device)\n    best_val = min(best_val, final_val)\n\n    return LMTrainResult(\n        tag=cfg.tag,\n        seed=cfg.seed,\n        total_steps=cfg.total_steps,\n        wall_time_s=wall,\n        steps_per_sec=cfg.total_steps / max(wall, 1e-9),\n        final_train_loss=train_loss,\n        final_val_loss=final_val,\n        best_val_loss=best_val,\n        val_losses=val_losses,\n        config=asdict(cfg),\n    )\n\n\ndef append_experiment_log(entry: dict, log_path: str = \"atlas/experiments_log.jsonl\") -> None:\n    path = Path(log_path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    with path.open(\"a\", encoding=\"utf-8\") as f:\n        f.write(json.dumps(entry, ensure_ascii=False) + \"\\n\")\n\n\ndef result_to_log_entry(result: LMTrainResult, command: str) -> dict:\n    return {\n        \"timestamp_utc\": time.strftime(\"%Y-%m-%dT%H:%M:%SZ\", time.gmtime()),\n        \"command\": command,\n        \"tag\": result.tag,\n        \"seed\": result.seed,\n        \"final_val_loss\": result.final_val_loss,\n        \"best_val_loss\": result.best_val_loss,\n        \"wall_time_s\": result.wall_time_s,\n        \"config\": result.config,\n    }\n",
    "atlas/optimizers.py": "\"\"\"Optimizers for ATLAS LM experiments.\"\"\"\n\nfrom __future__ import annotations\n\nimport torch\n\n\nclass SignLion(torch.optim.Optimizer):\n    \"\"\"Lion-style signed-momentum optimizer (SignLion).\"\"\"\n\n    def __init__(\n        self,\n        params,\n        lr: float = 1e-4,\n        betas: tuple[float, float] = (0.9, 0.99),\n        weight_decay: float = 0.0,\n    ) -> None:\n        defaults = dict(lr=lr, betas=betas, weight_decay=weight_decay)\n        super().__init__(params, defaults)\n\n    @torch.no_grad()\n    def step(self, closure=None):\n        loss = None\n        if closure is not None:\n            with torch.enable_grad():\n                loss = closure()\n\n        for group in self.param_groups:\n            lr = group[\"lr\"]\n            beta1, beta2 = group[\"betas\"]\n            wd = group[\"weight_decay\"]\n            for p in group[\"params\"]:\n                if p.grad is None:\n                    continue\n                g = p.grad\n                state = self.state[p]\n                if len(state) == 0:\n                    state[\"exp_avg\"] = torch.zeros_like(p)\n                exp_avg = state[\"exp_avg\"]\n\n                c = exp_avg.mul(beta1).add(g, alpha=1.0 - beta1)\n                p.add_(torch.sign(c), alpha=-lr)\n                if wd != 0.0:\n                    p.mul_(1.0 - lr * wd)\n                exp_avg.mul_(beta2).add_(g, alpha=1.0 - beta2)\n\n        return loss\n\n\ndef build_optimizer(name: str, params, lr: float, weight_decay: float):\n    name = name.lower()\n    if name == \"adamw\":\n        return torch.optim.AdamW(params, lr=lr, weight_decay=weight_decay)\n    if name == \"adam\":\n        return torch.optim.Adam(params, lr=lr, weight_decay=weight_decay)\n    if name == \"signlion\":\n        return SignLion(params, lr=lr, weight_decay=weight_decay)\n    raise ValueError(f\"Unknown optimizer: {name}\")\n",
}

for rel, src in ATLAS_SOURCES.items():
    p = Path(rel)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(src)

